package com.meshcrossway.android;
import java.util.*;
/** Telemetry field facts from the pinned official schema; retain unrecognized numeric fields by tag. */
final class MtMetrics {
    static String describe(int kind,byte[] bytes){StringBuilder out=new StringBuilder();for(Wire.F f:Wire.fields(bytes)){String name=label(kind,f.tag);String value;if(f.wire==5){float v=Float.intBitsToFloat((int)f.number);if(!Float.isFinite(v))continue;value=String.format(Locale.ROOT,"%.3f",v);}else if(f.wire==0||f.wire==1)value=Long.toString(f.number);else continue;if(out.length()>0)out.append(" · ");out.append(name).append(": ").append(value);if(out.length()>1000)break;}return out.toString();}
    static String label(int kind,int field){switch(kind){
case 2:switch(field){case 1:return "battery level";case 2:return "voltage";case 3:return "channel utilization";case 4:return "air util tx";case 5:return "uptime seconds";default:return "Field #"+field;}
case 3:switch(field){case 1:return "temperature";case 2:return "relative humidity";case 3:return "barometric pressure";case 4:return "gas resistance";case 5:return "voltage";case 6:return "current";case 7:return "iaq";case 8:return "distance";case 9:return "lux";case 10:return "white lux";case 11:return "ir lux";case 12:return "uv lux";case 13:return "wind direction";case 14:return "wind speed";case 15:return "weight";case 16:return "wind gust";case 17:return "wind lull";case 18:return "radiation";case 19:return "rainfall 1h";case 20:return "rainfall 24h";case 21:return "soil moisture";case 22:return "soil temperature";case 24:return "adc voltage ch0";case 25:return "adc voltage ch1";case 26:return "adc voltage ch2";case 27:return "adc voltage ch3";case 28:return "adc voltage ch4";case 29:return "adc voltage ch5";case 30:return "adc voltage ch6";case 31:return "adc voltage ch7";case 32:return "one wire temperature ch0";case 33:return "one wire temperature ch1";case 34:return "one wire temperature ch2";case 35:return "one wire temperature ch3";case 36:return "one wire temperature ch4";case 37:return "one wire temperature ch5";case 38:return "one wire temperature ch6";case 39:return "one wire temperature ch7";case 40:return "lightning strike count 1h";case 41:return "lightning distance km";default:return "Field #"+field;}
case 11:switch(field){case 1:return "soil ph";case 2:return "ph";case 3:return "electrical conductivity";case 4:return "salinity";case 5:return "nitrogen";case 6:return "phosphorus";case 7:return "potassium";case 8:return "dissolved oxygen";case 9:return "orp";case 10:return "chemical oxygen demand";case 11:return "turbidity";case 12:return "nitrate";case 13:return "ammonium";case 14:return "biochemical oxygen demand";case 15:return "solar irradiance";default:return "Field #"+field;}
case 5:switch(field){case 1:return "ch1 voltage";case 2:return "ch1 current";case 3:return "ch2 voltage";case 4:return "ch2 current";case 5:return "ch3 voltage";case 6:return "ch3 current";case 7:return "ch4 voltage";case 8:return "ch4 current";case 9:return "ch5 voltage";case 10:return "ch5 current";case 11:return "ch6 voltage";case 12:return "ch6 current";case 13:return "ch7 voltage";case 14:return "ch7 current";case 15:return "ch8 voltage";case 16:return "ch8 current";default:return "Field #"+field;}
case 4:switch(field){case 1:return "pm10 standard";case 2:return "pm25 standard";case 3:return "pm100 standard";case 4:return "pm10 environmental";case 5:return "pm25 environmental";case 6:return "pm100 environmental";case 7:return "particles 03um";case 8:return "particles 05um";case 9:return "particles 10um";case 10:return "particles 25um";case 11:return "particles 50um";case 12:return "particles 100um";case 13:return "co2";case 14:return "co2 temperature";case 15:return "co2 humidity";case 16:return "form formaldehyde";case 17:return "form humidity";case 18:return "form temperature";case 19:return "pm40 standard";case 20:return "particles 40um";case 21:return "pm temperature";case 22:return "pm humidity";case 23:return "pm voc idx";case 24:return "pm nox idx";case 25:return "particles tps";case 26:return "pm status flags";default:return "Field #"+field;}
case 6:switch(field){case 1:return "uptime seconds";case 2:return "channel utilization";case 3:return "air util tx";case 4:return "num packets tx";case 5:return "num packets rx";case 6:return "num packets rx bad";case 7:return "num online nodes";case 8:return "num total nodes";case 9:return "num rx dupe";case 10:return "num tx relay";case 11:return "num tx relay canceled";case 12:return "heap total bytes";case 13:return "heap free bytes";case 14:return "num tx dropped";case 15:return "noise floor";default:return "Field #"+field;}
case 9:switch(field){case 1:return "packets inspected";case 2:return "position dedup drops";case 3:return "nodeinfo cache hits";case 4:return "rate limit drops";case 5:return "unknown packet drops";case 6:return "hop exhausted packets";case 7:return "router hops preserved";default:return "Field #"+field;}
case 7:switch(field){case 1:return "heart bpm";case 2:return "spO2";case 3:return "temperature";default:return "Field #"+field;}
case 8:switch(field){case 1:return "uptime seconds";case 2:return "freemem bytes";case 3:return "diskfree1 bytes";case 4:return "diskfree2 bytes";case 5:return "diskfree3 bytes";case 6:return "load1";case 7:return "load5";case 8:return "load15";default:return "Field #"+field;}
default:return "Field #"+field;}}
    static String kind(int value){switch(value){case 2:return "Device";case 3:return "Environment";case 4:return "Air quality";case 5:return "Power";case 6:return "Local mesh";case 7:return "Health";case 8:return "Host";case 9:return "Traffic";case 11:return "Soil/water";default:return "Telemetry #"+value;}}
}
